function localDateToIso(v){if(!v)return null;return new Date(v+(v.length===16?':00':'')+'+05:30').toISOString();}
function sortEventsBySchedule(rows){var now=Date.now();return rows.slice().sort(function(a,b){var aPinned=Number(a.sort_order)<0,bPinned=Number(b.sort_order)<0;if(aPinned!==bPinned)return aPinned?-1:1;var aDate=a.starts_at?new Date(a.starts_at).getTime():Infinity,bDate=b.starts_at?new Date(b.starts_at).getTime():Infinity,aHas=Number.isFinite(aDate),bHas=Number.isFinite(bDate);if(aHas!==bHas)return aHas?-1:1;if(!aHas)return 0;var aFuture=aDate>=now,bFuture=bDate>=now;if(aFuture!==bFuture)return aFuture?-1:1;if(aFuture&&aDate!==bDate)return aDate-bDate;if(!aFuture&&aDate!==bDate)return bDate-aDate;return Math.abs(Number(a.sort_order)||0)-Math.abs(Number(b.sort_order)||0);});}
