 var now=Date.now(),week=now+7*86400000,soon=events.filter(function(x){var t=x.starts_at?new Date(x.starts_at).getTime():NaN;return x.is_published&&x.status!=='closed'&&Number.isFinite(t)&&t>=now&&t<=week;}).sort(function(a,b){return new Date(a.starts_at)-new Date(b.starts_at);});
 var drafts=events.filter(function(x){return !x.is_published;}).length,blogDrafts=blogPosts.filter(function(x){return x.status==='draft';}).length,undated=events.filter(function(x){return x.is_published&&x.status==='upcoming'&&!x.starts_at;}).length;
 var reminderItems=soon.map(function(x){return '<li><span><b>'+esc(x.title)+'</b><small>Starts '+esc(fmt(x.starts_at))+'</small></span><button class="text-btn" data-go="events">View</button></li>';});
 if(undated)reminderItems.push('<li><span><b>'+undated+' published event'+(undated===1?'':'s')+' need a date</b><small>Add a start date so visitors know when to attend.</small></span><button class="text-btn" data-go="events">Review</button></li>');
 if(drafts)reminderItems.push('<li><span><b>'+drafts+' unpublished event'+(drafts===1?'':'s')+'</b><small>These events are hidden from visitors.</small></span><button class="text-btn" data-go="events">Review</button></li>');
