function reviewPage(){var s='<div class="panel"><div class="panel-head"><div><h3>Community reviews</h3><p>Remove spam or inappropriate submissions.</p></div><span class="pill">'+reviews.length+' total</span></div>';if(!reviews.length)return s+'<div class="empty">No reviews yet.</div></div>';s+='<div class="table-wrap"><table><thead><tr><th>Member</th><th>Event</th><th>Rating</th><th>Review</th><th>Date</th><th></th></tr></thead><tbody>';reviews.forEach(function(r){s+='<tr><td><b>'+esc(r.display_name)+'</b></td><td>'+esc(r.event_title)+'</td><td>'+('★'.repeat(Number(r.rating)||0))+'</td><td>'+esc(r.review_text)+'</td><td>'+fmt(r.created_at)+'</td><td><button class="text-btn danger" data-delete-review="'+r.id+'">Delete</button></td></tr>';});return s+'</tbody></table></div></div>'; }
